#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,target;scanf("%d %d",&n,&target);
vector<int>a(n);int total=0;
for(int i=0;i<n;++i){scanf("%d",&a[i]);total+=a[i];}
if((total+target)%2||abs(target)>total){printf("0\n");return 0;}
int half=(total+target)/2;
vector<long long>dp(half+1,0);dp[0]=1;
for(int x:a)for(int j=half;j>=x;--j)dp[j]+=dp[j-x];
printf("%lld\n",dp[half]);return 0;}

